-- REM-A7-Q08-2 (2026-10-26, charter pillar reach (cost), session rem-a7-f2, agent_issues 100439, 100607). Follow-up to REM-A7-Q08-1 (migration_runs 678): two more q08 changes found while measuring the first one, and a correction of
-- the baseline the metric reports. Read-only evidence: the q08-signal D1 (engine_runs, signal_log, q08_forecasts, published_pieces) and live q08.org reads between 18:00Z and 19:25Z on 2026-10-26.
--   q08-signal-engine 0.37.4 (PR 4835, merged 19:16Z, live 19:19Z): the writer gate refused every comma-grouped dollar amount and every "score of 0.85" without reading the source; six runs since 2026-10-19 ended there with all six
--     composes spent (run 958: the story headline is about $2.5M and the draft said $2,484,599; three of them were arXiv papers).
--   q08-signal-engine 0.37.5 (PR 4848): a measured-thin candidate passed over for a richer one was never marked, so one arXiv paper without an HTML rendering held the whole arXiv lane (the lane ran at 02:02 and 03:04 and then
--     not for 16 hours; 2610.32638 answers 404 and sat first with 9 renderable papers behind it).
--   The first run after the pool change (run 1002, 19:08Z) chose an arXiv paper that only the 100-submission pool reaches, passed the grounding check, the panel and 21 fact-check calls, and failed at the final read (mean 2 of 5).
--   Baseline correction: q08_neurons_per_published_piece_7d counts every published_pieces row, so the 4 hand-researched pieces of 2026-10-26 (3 forecasts and one essay, written outside the engine) are in its denominator. Engine only:
--     3 pieces in 7 days for 1,256,947 neurons, about 419,000 neurons an engine piece, not the 179,564 the metric reads.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE agent_issues SET description = substr(description, 1, instr(description, char(10) || char(10) || 'UPDATE 2026-10-26 19:25Z (REM-A7-Q08-2') - 1) WHERE id = 100439 AND instr(description, 'UPDATE 2026-10-26 19:25Z (REM-A7-Q08-2') > 0; UPDATE issue_triage SET remediation = substr(remediation, 1, instr(remediation, ' REM-A7-Q08-2 (19:25Z)') - 1) WHERE issue_id IN (100439, 100607) AND instr(remediation, ' REM-A7-Q08-2 (19:25Z)') > 0
-- (the decision_log row stays: the table is append-only)

UPDATE agent_issues SET description = COALESCE(description, '') || char(10) || char(10) ||
  'UPDATE 2026-10-26 19:25Z (REM-A7-Q08-2, session rem-a7-f2). Measured after the first lever went live (q08-signal-engine 0.37.2, 18:34Z): (1) the first post-deploy run, 1002 at 19:08Z, chose an arXiv paper that the 100-submission pool reaches and the old 30-submission window did not; it passed grounding, the panel and 21 fact-check calls and failed at the final read (mean 2 of 5), so the lever opens the lane and the quality bar still decides. (2) The lane was blocked by a pre-existing flaw: a candidate measured thin and passed over was never marked, and only the first unprocessed paper of the lane is ever tried, so one paper with no HTML rendering (2610.32638, arxiv.org/html answers 404) held the lane: it ran at 02:02 and 03:04 on 2026-10-26 and then not for 16 hours with 9 renderable papers behind it. Fixed in 0.37.5 (PR 4848, Q08-THIN-PASSED-OVER-1). (3) The writer gate refused every comma-grouped dollar amount and every "score of 0.85" without reading the source; six runs of 2026-10-19 to 26 ended there with six composes each (run 958: the story headline is about $2.5M and the draft said $2,484,599; three were arXiv papers). Fixed in 0.37.4 (PR 4835, Q08-GATE-GROUND-BLIND-1); the grounding check, which runs before any panel call and on the final text, still refuses a figure the source does not hold. (4) Baseline correction: q08_neurons_per_published_piece_7d counts every published piece, including the 4 hand-researched pieces of 2026-10-26 written outside the engine, so it reads 179,564; the engine alone published 3 pieces in 7 days for 1,256,947 neurons, about 419,000 an engine piece (about 4.6 USD). The prediction above stands on the metric as it is computed: with the arXiv lane open at 40 percent of runs and an arXiv yield of 7.8 percent against 1.4 percent, expect about 3 times the engine pieces a week at the same neuron budget. The probe of this issue reads the metric and stays red until the pass rate and the cost reach its targets, which the quality bar makes unlikely; nothing is edited to pass.',
  updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE id = 100439 AND status = 'open' AND instr(COALESCE(description, ''), 'REM-A7-Q08-2') = 0;

UPDATE issue_triage SET remediation = COALESCE(remediation, '') || ' REM-A7-Q08-2 (19:25Z): also live or merged since: 0.37.4 (PR 4835, the writer gate no longer refuses source-supported dollar amounts and decimal scores), 0.37.5 (PR 4848, a thin candidate passed over is marked so one no-rendering paper does not hold the arXiv lane). Read on 2026-10-29: arXiv share of finished runs (engine_runs by source prefix, expected 40 percent or more) and the count of runs ending at the currency or decimal checks (expected 0).'
WHERE issue_id = 100439 AND instr(COALESCE(remediation, ''), 'REM-A7-Q08-2') = 0;

UPDATE issue_triage SET remediation = COALESCE(remediation, '') || ' REM-A7-Q08-2 (19:25Z): two more causes of refused drafts removed: the writer gate refused every comma-grouped dollar amount and every "score of 0.85" without reading the source (0.37.4, PR 4835; six runs since 2026-10-19), and one paper with no HTML rendering held the arXiv lane (0.37.5, PR 4848).'
WHERE issue_id = 100607 AND instr(COALESCE(remediation, ''), 'REM-A7-Q08-2') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a7-f2',
  'a gate that cannot see the source must not refuse what the source states, and a lane of candidates must advance past one that cannot be used',
  'REM-A7-Q08-2: q08-signal-engine 0.37.4 drops the two ground-blind checks of the writer gate (comma-grouped dollar amounts, score or ratio decimals); 0.37.5 marks a measured-thin candidate that a richer one was chosen over; the 100439 and 100607 records updated',
  'engine_runs 958, 993, 821 (amounts) and 834, 940, 785 (decimals) each ended at those checks with 6 composes; signal_log: the arXiv lane ran at 02:02 and 03:04 on 2026-10-26 and next at 19:08, with 2610.32638 (arxiv.org/html 404) first and 9 renderable papers behind it; run 1002 (19:08Z) arXiv, grounding and panel and 21 fact-check calls passed, final read 2 of 5; PR 4835 merged 19:16Z and q08.org/health 0.37.4-ground-blind 19:19Z; offline suites ground-blind-gate.test.mjs (fails 6 of 14 on the previous worker) and thin-passed-over.test.mjs (generate-level checks fail on the previous worker)',
  'pending: engine_runs read on 2026-10-29 (arXiv share of finished runs, runs ending at the currency or decimal checks) and the metrics on 2026-11-02',
  'q08.org candidate mix and the figures a draft may state (the grounding check still decides every figure); no cap, bar, order or model changes',
  'revert the 0.37.4 and 0.37.5 commits; ops_config q08_arxiv_pool = 30 restores the earlier pool',
  'a lane that advances past an unusable candidate; a writer gate that no longer contradicts the grounding check',
  'arXiv share of finished runs 22 percent -> 40 percent or more within 3 days; zero runs ending at the removed checks; about 3 times the engine pieces a week at the same neuron budget',
  'q08.org: more published pieces a week, with their figures',
  'q08-signal D1 engine_runs, signal_log (SELECT only); live q08.org /health and /api/runs; offline node:sqlite suite migrations/rem-a7-q08-2.test.mjs and the q08-signal-engine suites'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE instr(action, 'REM-A7-Q08-2:') = 1);
